import sys
from collections import deque, defaultdict

class Node:
    def __init__(self, val):
        self.val = val
        self.left = None
        self.right = None

def build_tree_and_find_home(data, home_val):
    if not data:
        return None, None

    lines = data.strip().split('\n')
    if not lines:
        return None, None

    n = int(lines[0])
    edges = []
    for i in range(1, n + 1):
        parts = lines[i].split()
        u = int(parts[0])
        v = int(parts[1])
        edges.append((u, v))

    adj = defaultdict(list)
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    root = None
    visited = set()
    queue = deque([1])
    visited.add(1)
    while queue:
        curr = queue.popleft()
        if root is None:
            root = curr
        for neighbor in adj[curr]:
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append(neighbor)

    home_node = None
    if home_val in adj or any(home_val == u for u, v in edges) or any(home_val == v for u, v in edges):
        home_node = home_val
    else:
        for node_val in adj:
            if node_val == home_val:
                home_node = node_val
                break

    return root, home_node, adj

def main():
    input_data = sys.stdin.read()
    if not input_data:
        return

    lines = input_data.strip().split('\n')
    try:
        n = int(lines[0])
        edges = []
        for i in range(1, n + 1):
            parts = lines[i].split()
            u = int(parts[0])
            v = int(parts[1])
            edges.append((u, v))

        last_line = lines[n + 1]
        params = last_line.split()
        home = int(params[0])
        k = int(params[1])
    except IndexError:
        return

    adj = defaultdict(list)
    for u, v in edges: adj[u].append(v); adj[v].append(u)

    visited = set()
    queue = deque([(home, 0)])
    visited.add(home)
    total = 0

    while queue:
        curr, dist = queue.popleft()
        total += curr
        if dist < k:
            for neighbor in adj[curr]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append((neighbor, dist + 1))

    print(total)

if __name__ == "__main__":
    main()
